"""Audit products.csv for data-quality issues.

Rules:
  negative_price : price < 0
  blank_name     : name is empty/whitespace
  duplicate_sku  : every row whose sku occurs more than once

Returns {rule: [offending rows]} preserving file order within a rule.
"""
from __future__ import annotations

import csv
from collections import Counter
from pathlib import Path

CSV_PATH = Path(__file__).with_name("products.csv")


def load_rows(path: Path = CSV_PATH) -> list[dict]:
    with path.open(newline="", encoding="utf-8") as fh:
        return list(csv.DictReader(fh))


def audit(rows: list[dict]) -> dict[str, list[dict]]:
    findings: dict[str, list[dict]] = {
        "negative_price": [],
        "blank_name": [],
        "duplicate_sku": [],
    }

    sku_counts = Counter(r["sku"] for r in rows)

    for idx, row in enumerate(rows):
        price = float(row["price"])
        if price < 0:
            findings["negative_price"].append({"line": idx + 2, **row})
        if not row["name"].strip():
            findings["blank_name"].append({"line": idx + 2, **row})
        if sku_counts[row["sku"]] > 1:
            findings["duplicate_sku"].append({"line": idx + 2, **row})

    return findings


def main(path: Path = CSV_PATH) -> dict[str, list[dict]]:
    return audit(load_rows(path))


if __name__ == "__main__":
    findings = main()
    for rule, hits in findings.items():
        print(f"{rule}: {len(hits)}")

